corrected_code:
export const fileRouter = router({
  getFileDetails: protectedProcedure
    .input(z.object({ fileId: z.string().uuid() }))
    .query(async ({ input, ctx }) => {
      const file = await ctx.prisma.storedFile.findFirst({
        where: { id: input.fileId, ownerId: ctx.user.id },
      });
      if (!file) throw new TRPCError({ code: 'FORBIDDEN', message: 'Access denied to target file' });
      return file;
    }),
});
